+
@@ -8487,22 +8491,70 @@
-    vpclmulqdq(xmm2, xmm0, xmm1, 0x1);
-    vpand(xmm3, xmm0, xmm2, 0 /* vector_len */);
-    vpclmulqdq(xmm0, xmm0, xmm3, 0x1);
-  } else {
-    movdqa(xmm2, xmm0);
-    pclmulqdq(xmm2, xmm1, 0x1);
